function assistantPolishedBotReply(text,post){const value=String(text||'').trim(),source=String(post?.target_text||post?.caption||'');if(value.length<18)return false;const explanatory=/(?:nhìn|xem|qua|dựa\s+vào).{0,50}(?:thì|nên|cũng|là).{0,70}(?:không\s+lạ|dễ\s+hiểu|đáng\s+kể|ra\s+ngay|thành\s+con\s+số\s+lớn)|(?:mỗi|từng).{0,45}(?:cộng\s+lại|gom\s+lại|tính\s+ra).{0,50}(?:không\s+lạ|đáng\s+kể|ra\s+số)|(?:có\s+vẻ|dường\s+như).{0,90}(?:tối\s+ưu|hiệu\s+suất|đáng\s+kể|không\s+lạ)|(?:phần\s+thưởng|được\s+đền\s+đáp|xứng\s+đáng).{0,70}(?:cho|vì|bởi)/iu.test(value);if(!explanatory)return false;const conversational=/(?:nhỉ|ha|hả|ghê|thật|đấy|đó|quá|nè|mà|t|bro|bác|ông|bà|kiểu|chắc)/iu.test(value);const sourceOverlap=normalizeReplyText(value).split(' ').filter(w=>w.length>2&&normalizeReplyText(source).includes(w)).length;return !conversational&&sourceOverlap<3}
const assistantValidateTranslationsNatural=validateTranslations;validateTranslations=function(result,post,allowMissing=false){if((result?.replies||[]).some(item=>assistantPolishedBotReply(item?.reply,post)))throw new Error('Câu trả lời quá tròn trịa hoặc mang tính giải thích như bot. Hãy viết lại ngắn, khẩu ngữ, như một phản xạ tự nhiên trên X và không kết luận vượt dữ kiện.');return assistantValidateTranslationsNatural(result,post,allowMissing)};
const assistantReplyInstructionsNatural=replyInstructions;replyInstructions=function(message){return assistantReplyInstructionsNatural(message)+' Human-naturalness rule: replies must sound like a real short X reaction, not an explanation of the evidence. Prefer one clear thought, everyday wording and natural Vietnamese particles when appropriate. Avoid polished templates such as “nhìn ... thì không lạ”, “mỗi ... cộng lại”, “có vẻ họ ... để tối ưu hiệu suất”, “được đền đáp”, “phần thưởng xứng đáng”. Do not narrate why the conclusion follows; react directly to the exact wording. Keep uncertainty only when needed and express it briefly.'};
const assistantRetryReasonNatural=retryReason;retryReason=function(error){if(/tròn trịa|giải thích như bot|phản xạ tự nhiên/iu.test(String(error?.message||'')))return'Viết lại như phản xạ thật trên X: một ý ngắn, khẩu ngữ, bám đúng câu người đăng và không giải thích quy trình suy luận. Tránh các mẫu “nhìn ... thì không lạ”, “mỗi ... cộng lại”, “có vẻ ... tối ưu hiệu suất”, “được đền đáp”, “phần thưởng xứng đáng”.';return assistantRetryReasonNatural(error)};
const assistantHumanTemplateReply=/(?:đúng là|chúc mừng .* cột mốc|khó cưỡng|tràn đầy năng lượng|chắc chắn sẽ|không thể không|quả ngọt|xứng đáng với|nhìn .* là thấy|nhìn .* là hiểu)/iu;
const assistantValidateHumanNatural=validateTranslations;validateTranslations=function(result,post,allowMissing=false){const replies=result?.replies||[];const repeated=replies.map(item=>String(item?.reply||'').trim().toLocaleLowerCase()).filter(Boolean);if(repeated.length>1&&new Set(repeated.map(x=>x.replace(/[^\p{L}\p{N} ]/gu,'').split(/\s+/).slice(0,4).join(' '))).size<repeated.length)throw new Error('Các gợi ý quá giống nhau. Hãy tạo các phản xạ khác góc nhìn và khác nhịp câu.');if(replies.some(item=>assistantHumanTemplateReply.test(String(item?.reply||''))))throw new Error('Câu trả lời dùng mẫu khen hoặc công thức quá quen thuộc. Hãy viết như một người đang phản ứng nhanh trên X: một ý ngắn, khẩu ngữ, bám một chi tiết và không tóm tắt lại bài.');return assistantValidateHumanNatural(result,post,allowMissing)};
const assistantReplyInstructionsHuman=replyInstructions;replyInstructions=function(message){return assistantReplyInstructionsHuman(message)+' Strict human voice: do not begin every option with “đúng là”, “nhìn”, or “chúc mừng”. For casual food, shopping, lifestyle or milestone posts, react to one concrete detail with a short spoken Vietnamese phrase; a fragment or ending particle such as “á”, “nha”, “ghê”, “rồi đó” is acceptable when natural. Do not praise generically, restate the post, explain why it is good, or force a joke. Make alternatives genuinely different in angle and rhythm; at least one may be very short. Never optimize for polished wording.'};
function botStyleReply(text){const value=String(text||'').trim();return /^(?:dòng tiền|điều này|nhìn chung|có thể là|cũng có thể là|rõ ràng là|qua đó cho thấy|đây là dấu hiệu).{0,180}(?:đang|cho thấy|đáng chú ý|chuẩn bị|tăng mạnh|giảm mạnh|thanh khoản|thị trường)/iu.test(value)||/(?:đang chuẩn bị|có khả năng sẽ|cho thấy rõ|đáng chú ý là).{0,80}(?:cá voi|thị trường|giá|dòng tiền|thanh khoản)/iu.test(value)}
const assistantValidateBotStyle=validateTranslations;validateTranslations=function(result,post,allowMissing=false){if((result?.replies||[]).some(item=>botStyleReply(item?.reply)))throw new Error('Gợi ý mang văn phong báo cáo hoặc suy đoán máy móc. Hãy viết lại như một người dùng X, ngắn và có góc nhìn cụ thể.');return assistantValidateBotStyle(result,post,allowMissing)};
